head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS90001.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.gform_onload = function() {
    //파라미터추출
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        var param = '';
        param += "&{P}V_BND_APPL_ID=" + arrPar[0].BND_APPL_ID; //채권신청ID
        param += "&{P}V_BND_LIST_PROCS_TP_CD=" + arrPar[0].BND_LIST_PROCS_TP_CD; //채권처리구분(1:신청,2:접수)

        //첨부문서조회
        var dsNm = 'BNS_ATTACH_DOC';
        var qryId = 'lds.stf.bnscommon.select.listAttachDoc';
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.grd_List_OnDblClick = function(row, colid) {
    var url = "/bns/BnsAttachDocFileDownload.do?";
    url += "ATTACH_FILE_TP_CD=" + dts_List.getCellData(row, "ATTACH_FILE_TP_CD");
    url += "&FAX_IMG_FILE_NM=" + dts_List.getCellData(row, "FAX_IMG_FILE_NM");
    url += "&ISUR_CD=" + dts_List.getCellData(row, "ISUR_CD");
    url += "&APPL_DD=" + dts_List.getCellData(row, "APPL_DD");
    url += "&APPL_TM=" + dts_List.getCellData(row, "APPL_TM");
    url += "&DISCLS_DOC_NO=20121129000367";
    url += "&ATTACH_SEQ=1";
    location.href = url;
};
